package hexadecimal

import (
	"errors"
	"math"
)

var (
	errSyntax = errors.New("syntax error: invalid hexadecimal input")
	errRange  = errors.New("range error: value out of range for int64")
)

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent using first principles, without relying on any library that
// performs the conversion itself.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errSyntax
	}

	var n int64
	for _, c := range in {
		var d int64
		switch {
		case c >= '0' && c <= '9':
			d = int64(c - '0')
		case c >= 'a' && c <= 'f':
			d = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int64(c-'A') + 10
		default:
			return 0, errSyntax
		}

		// n*16+d would overflow int64 iff n > (MaxInt64-d)/16.
		if n > (math.MaxInt64-d)/16 {
			return 0, errRange
		}
		n = n*16 + d
	}
	return n, nil
}

// HandleErrors runs ParseHex over each input and reports "none", "syntax",
// or "range" for each, according to the error returned.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		if _, err := ParseHex(in); err == nil {
			results[i] = "none"
		} else if errors.Is(err, errRange) {
			results[i] = "range"
		} else {
			results[i] = "syntax"
		}
	}
	return results
}
